INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-001","slug":"florence-28-ans-genou-droit","titre":"Florence, 28 ans — Genou droit craquant et douloureux","statut":"publie","niveau_complexite":2,"age":28,"sexe":"feminin","cas_complet":true,"exemplaire":true,"grille_principale":"yin_yang","tags":["genou","méridien VB","mononucléose","danse","Yin/Yang","séquelles"],"content":{"motif":"Genou droit qui craque et est douloureux depuis 2 mois.","interrogatoire":[{"cle":"douleur","valeur":"Craquement sonore à la marche uniquement — pas en sautant ni en courant. Amélioration quand la jambe est repliée (torsion légère)."},{"cle":"horaire","valeur":"Douleur la nuit au repos. Pas de gêne en marchant ni en dansant."},{"cle":"activite","valeur":"Danseuse classique et contemporaine — 6 à 10h de pratique par semaine, en 3 séances."},{"cle":"traumatisme","valeur":"Aucun traumatisme identifié."},{"cle":"preferences","valeur":"Aime la pluie. N''aime pas le ski. Aime la montagne."},{"cle":"antecedents","valeur":"Mononucléose avec atteinte hépatique il y a 7 ans. Fatiguée pendant 2 ans. Fatigabilité persistante depuis."}],"observation":"Aspect du genou strictement normal, identique à l''autre. Pas de gonflement visible.","palpation":"Nombreux ganglions le long du sterno-cléido-mastoïdien (trajets TR et VB). Température normale au genou. Aucun point douloureux à la pression locale.","prisePouls":{"condition":"Patient allongé, bras détendu","lectures":[{"position":"foyer_inferieur_gauche","qualites":["vide"],"interpretation":"Vide de Yang au Foyer Inférieur gauche — insuffisance Yang générale."},{"position":"foyer_moyen_droit","qualites":["large","mou"],"interpretation":"Pouls trop large et mou à droite en profond : Yin en excès avec vide de Yang."},{"position":"specifique","positionLabel":"9P (Poumon en surface)","qualites":["vide"],"interpretation":"9P vide : énergie interne et bas du corps insuffisante."},{"position":"foyer_moyen_gauche","qualites":["plein"],"interpretation":"Rate forte : Yin en excès au Foyer Moyen."}],"synthese":"Tableau de vide de Yang général avec excès de Yin. Foyer moyen chargé. Le Yang ne monte pas correctement vers les membres inférieurs."},"contexteVie":"Pratique intense de la danse depuis l''adolescence. Antécédent de mononucléose ayant affaibli l''axe hépatique (Foie/Vésicule Biliaire)."},"view_count":312,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-09-01","updated_at":"2026-05-11T16:12:09.073Z","date_creation":"2025-09-01","date_publication":"2025-09-15"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-002","slug":"jean-charles-crise-goutte-orteil","titre":"Jean-Charles — Goutte : orteil gauche douloureux","statut":"publie","niveau_complexite":2,"age":null,"sexe":"masculin","cas_complet":true,"exemplaire":false,"grille_principale":"yin_yang","tags":["goutte","orteil","acide urique","Vésicule Biliaire","Foie","Rate","psychisme"],"content":{"motif":"Crise de goutte il y a 1 an au gros orteil gauche. État latent de douleur persistant.","interrogatoire":[{"cle":"declencheur","valeur":"Crise à chaque période difficile ou lors de problèmes — lien direct avec l''état émotionnel."},{"cle":"localisation","valeur":"Gros orteil gauche, douleur persistante à bas bruit entre les crises."},{"cle":"historique","valeur":"Première crise diagnostiquée il y a 1 an, acide urique confirmé à l''analyse."}],"observation":"Orteil rouge, gonflé, congestif dans la zone douloureuse. Aspect inflammatoire.","palpation":"Tous les points locaux sensibles et douloureux à faible pression → aspect Yang et plénitude. Orteil chaud à la palpation.","prisePouls":{"condition":"Patient assis, bras détendu","lectures":[{"position":"foyer_inferieur_droit","qualites":["plein","profond"],"interpretation":"Plus fort en profondeur à droite — Yin plus fort."},{"position":"global_superficiel","qualites":["absent"],"interpretation":"Pas de Yang, absence de pouls superficiels — vide de Yang général."}],"synthese":"Yang local (inflammation, chaleur, plénitude locale) sur fond de vide de Yang général. Paradoxe diagnostique classique : Yang local bruyant masquant le vide profond."}},"view_count":178,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-09-05","updated_at":"2026-05-11T16:12:09.074Z","date_creation":"2025-09-05","date_publication":"2025-09-20"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-003","slug":"diarrhees-petit-matin-vide-yang-rein","titre":"Diarrhées chroniques du petit matin — vide de Yang Rein","statut":"publie","niveau_complexite":2,"age":null,"sexe":null,"cas_complet":true,"exemplaire":true,"grille_principale":"zang_fu","tags":["diarrhées","petit matin","Rein","Yang","Ming Men","Foyer Inférieur"],"content":{"motif":"Diarrhées persistantes depuis plusieurs mois, survenant systématiquement au petit matin, entre 5h et 7h.","interrogatoire":[{"cle":"horaire","valeur":"Diarrhées exclusivement au petit matin (5h-7h), au moment où les Souffles Yang doivent monter en puissance."},{"cle":"selles","valeur":"Selles semi-liquides, peu douloureuses. Pas de crampes violentes."},{"cle":"general","valeur":"Visage terne, teint légèrement noirâtre. Esprit fatigué, manque d''entrain matinal."},{"cle":"traitement_froid_chaleur","valeur":"Amélioration avec la chaleur. Aggravation au froid et en hiver."},{"cle":"urine","valeur":"Urines claires, abondantes, parfois nocturies."},{"cle":"lombalgie","valeur":"Sensation de froid et faiblesse lombaire chronique, aggravée par le froid."}],"prisePouls":{"condition":"Patient allongé, début de matinée","lectures":[{"position":"foyer_inferieur_gauche","qualites":["vide","profond"],"interpretation":"Pouls submergé, profond, fin au Foyer Inférieur — vide du Yang de Ming Men."},{"position":"global_profond","qualites":["vide","lent"],"interpretation":"Pouls global profond, vide, lent — confirme le tableau de vide de Yang."}],"synthese":"Vide profond du Yang du Rein — Ming Men insuffisant. Les Souffles Yang ne montent pas au petit matin (heure Yang Ming), laissant le Froid envahir le Réchauffeur Moyen."},"contexteVie":"Surmenage chronique depuis plusieurs années. Exposition répétée au froid. Alimentation irrégulière."},"view_count":224,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-10-10","updated_at":"2026-05-11T16:12:09.074Z","date_creation":"2025-10-10","date_publication":"2025-10-25"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-004","slug":"hypertension-vide-yin-rein-yang-foie","titre":"Hypertension — Vide de Yin Rein, prospérité du Yang Foie","statut":"publie","niveau_complexite":3,"age":null,"sexe":null,"cas_complet":true,"exemplaire":true,"grille_principale":"cinq_elements","tags":["hypertension","Rein","Foie","Yin","Yang","Cinq Éléments","Eau/Bois"],"content":{"motif":"Hypertension artérielle diagnostiquée et suivie. Maux de tête, vertiges, bourdonnements d''oreille, insomnies.","interrogatoire":[{"cle":"symptomes_tete","valeur":"Maux de tête frontaux et temporaux. Vertiges à l''effort, sensation de tête qui tourne."},{"cle":"oreilles","valeur":"Bourdonnements d''oreille permanents, aggravés à la fatigue."},{"cle":"sommeil","valeur":"Insomnies : endormissement difficile, réveils nocturnes avec agitation."},{"cle":"coeur","valeur":"Palpitations cardiaques intermittentes, sans anomalie organique."},{"cle":"aspect","valeur":"Corps amaigri. Visage rouge. Yeux parfois rouges."},{"cle":"psychisme","valeur":"Esprit (Shen) fatigué — difficultés de concentration, irritabilité."},{"cle":"desirs","valeur":"Désirs sexuels marqués dans les antécédents. Soucis et détérioration du Sang par surcharge émotionnelle prolongée."}],"prisePouls":{"condition":"Patient assis, bras détendus","lectures":[{"position":"foyer_inferieur_gauche","qualites":["vide","profond"],"interpretation":"Vide profond au Rein gauche — insuffisance du Yin du Rein."},{"position":"foyer_superieur_gauche","qualites":["rapide","corde_arc"],"interpretation":"Pouls corde-arc au Foie, rapide — Yang du Foie montant, vent interne."},{"position":"global_superficiel","qualites":["plein","rapide"],"interpretation":"Pouls superficiel plein et rapide — Yang monté en surface, chaleur."}],"synthese":"Vide de Yin du Rein laissant le Yang du Foie monter en usurpateur. L''Eau ne contient plus le Bois. Tableau classique d''hypertension par vide."},"contexteVie":"Vie active avec surcharge émotionnelle chronique. Antécédents de détérioration du Sang (soucis, fatigues prolongées). L''hypertension s''est installée progressivement."},"view_count":287,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-10-20","updated_at":"2026-05-11T16:12:09.074Z","date_creation":"2025-10-20","date_publication":"2025-11-05"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-005","slug":"bourdonnements-oreille-surdite-vide-yin-rein","titre":"Bourdonnements d''oreille chroniques — vide de Yin Rein","statut":"publie","niveau_complexite":3,"age":null,"sexe":null,"cas_complet":false,"exemplaire":false,"grille_principale":"zang_fu","tags":["surdité","bourdonnements","oreille","Rein","Vésicule Biliaire","Shao Yang","Yin"],"content":{"motif":"Bourdonnements d''oreille chroniques et intermittents depuis 2 ans. Légère diminution de l''acuité auditive.","interrogatoire":[{"cle":"caracteristiques_son","valeur":"Bruits continus mais tenus, type bruit de cigale ou flûte. Pas de flux/reflux (exclut la plénitude)."},{"cle":"aggravation","valeur":"S''accroissent nettement à la fatigue. Présents depuis un épisode de forte surcharge professionnelle."},{"cle":"vertiges","valeur":"Étourdissements légers, vertiges doux — pas de vertige rotatoire."},{"cle":"lombaires","valeur":"Lombalgies de fond, sensation de froid dans le bas du dos."},{"cle":"fatigue","valeur":"Fatigue profonde, surtout en fin de journée. Se sent ''vide''."},{"cle":"historique","valeur":"Début progressif, lié à une période d''épuisement. Pas d''épisode infectieux ni traumatique."}],"prisePouls":{"condition":"Patient allongé, en début de séance","lectures":[{"position":"foyer_inferieur_gauche","qualites":["vide","profond","etroit"],"interpretation":"Vide profond et étroit au Rein gauche — vide de Yin du Rein, Feu du vide."},{"position":"foyer_superieur_gauche","qualites":["vide"],"interpretation":"Foyer Supérieur gauche léger — Shen perturbé par l''insuffisance du Yin."}],"synthese":"Vide de Yin du Rein avec montée de la chaleur du vide. Le Yin des Reins est insuffisant — les liquides ne peuvent plus ancrer le Yang ascendant. Tableau de bourdonnements par vide (différentiel : bourdonnements continus, tenus, aggravés à la fatigue)."},"contexteVie":"Professionnel en surmenage chronique. Épisode d''épuisement sévère il y a 3 ans, sans récupération complète.","antecedents":"Aucun traumatisme auditif. Pas d''otite chronique. Pas d''antécédents familiaux de surdité."},"view_count":143,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-11-15","updated_at":"2026-05-11T16:12:09.074Z","date_creation":"2025-11-15","date_publication":"2025-12-01"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-006","slug":"thomas-45-ans-lombalgie-chronique","titre":"Thomas, 45 ans — Lombalgie chronique et grande fatigue","statut":"publie","niveau_complexite":1,"age":45,"sexe":"masculin","cas_complet":true,"exemplaire":false,"grille_principale":"yin_yang","tags":["lombalgie","rein","fatigue","Yang vide","Ming Men"],"content":{"motif":"Lombalgie chronique depuis 4 ans avec irradiation dans la fesse droite. Grande fatigue en fin de journée.","interrogatoire":[{"cle":"douleur","valeur":"Douleur sourde et profonde dans le bas du dos. Aggravée au repos prolongé et le matin au réveil. Améliorée par la chaleur et le mouvement."},{"cle":"horaire","valeur":"Pire le matin au lever. Mieux après activité douce. Rechutes en hiver et par temps froid."},{"cle":"urines","valeur":"Urines claires et abondantes, surtout la nuit (2-3 levées). Légère incontinence d''effort."},{"cle":"froid","valeur":"Froid aux pieds et aux genoux. Aime les bains chauds. Frileuse."},{"cle":"antecedents","valeur":"Surmenage professionnel depuis 10 ans. Père opéré du dos (hernie discale L4-L5)."}],"observation":"Patient pâle, voix basse. Dos courbé légèrement en avant. Pas de déficit neurologique.","prisePouls":{"condition":"Patient allongé, bras détendu","lectures":[{"position":"foyer_inferieur_gauche","qualites":["vide","profond"],"interpretation":"Vide profond au Foyer Inférieur gauche — Yang du Rein insuffisant."},{"position":"foyer_inferieur_droit","qualites":["vide","profond"],"interpretation":"Vide profond bilatéral confirmant le vide Yang général du Rein."},{"position":"global_profond","qualites":["lent","faible"],"interpretation":"Pouls global lent et faible — vide de Yang constitutionnel profond."}],"synthese":"Vide de Yang du Rein et du Ming Men. La lenteur globale confirme le froid interne. Traiter le Yang du Foyer Inférieur en priorité absolue."}},"view_count":187,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-10-01","updated_at":"2026-05-11T16:12:09.074Z","date_creation":"2025-10-01","date_publication":"2025-10-15"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-007","slug":"sophie-42-ans-cervicalgies-cephalees","titre":"Sophie, 42 ans — Cervicalgies, céphalées temporales et insomnie","statut":"publie","niveau_complexite":2,"age":42,"sexe":"feminin","cas_complet":true,"exemplaire":false,"grille_principale":"yin_yang","tags":["céphalées","cervicalgies","insomnie","Yang Foie montant","Yin Rein"],"content":{"motif":"Cervicalgies persistantes avec céphalées temporales récurrentes et insomnie depuis 8 mois.","interrogatoire":[{"cle":"cephalees","valeur":"Céphalées temporales bilatérales, pulsatiles. Aggravées par le stress et les menstruations. Soulagées par la pression froide."},{"cle":"cervicalgies","valeur":"Raideur cervicale matinale. Tension dans la nuque et les épaules. Pas de névralgie cervico-brachiale."},{"cle":"sommeil","valeur":"Endormissement difficile. Réveils nocturnes entre 1h et 3h. Rêves agités, parfois cauchemars. Fatigue matinale persistante."},{"cle":"emotionnel","valeur":"Stress professionnel important. Irritabilité. Difficultés à décompresser en soirée."},{"cle":"regles","valeur":"Cycle raccourci (23-24 jours). Saignements plus abondants depuis 1 an. Céphalées systématiques J2-J3."}],"observation":"Teint rouge, yeux brillants. Tension dans les trapèzes et les muscles sous-occipitaux.","prisePouls":{"condition":"Patient allongé après 5 min de repos","lectures":[{"position":"foyer_moyen_gauche","qualites":["corde_arc","rapide"],"interpretation":"Pouls en corde-arc rapide au Foyer Moyen gauche — Yang du Foie montant."},{"position":"foyer_inferieur_gauche","qualites":["vide","profond"],"interpretation":"Foyer Inférieur gauche vide profond — Yin du Rein insuffisant (cause profonde)."},{"position":"foyer_superieur_gauche","qualites":["rapide"],"interpretation":"Cœur rapide — Shen légèrement perturbé par le manque de Yin."}],"synthese":"Vide de Yin du Rein → Yang du Foie non ancré → monte vers le haut. Traiter le Rein en premier, le Foie en second."}},"view_count":143,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-10-20","updated_at":"2026-05-11T16:12:09.075Z","date_creation":"2025-10-20","date_publication":"2025-11-05"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-008","slug":"marie-36-ans-fatigue-anxiete-insomnie","titre":"Marie, 36 ans — Fatigue profonde, anxiété et insomnie","statut":"publie","niveau_complexite":2,"age":36,"sexe":"feminin","cas_complet":true,"exemplaire":false,"grille_principale":"zang_fu","tags":["fatigue","anxiété","insomnie","Shen","Cœur","Rein","vide Yin"],"content":{"motif":"Fatigue chronique profonde avec anxiété permanente et difficultés d''endormissement depuis 1 an. Épuisement après effort minime.","interrogatoire":[{"cle":"fatigue","valeur":"Fatigue dès le matin au lever. Coup de pompe entre 11h et 13h. Épuisement total en soirée. Pas améliorée par le repos."},{"cle":"sommeil","valeur":"Endormissement difficile (1-2h). Réveils entre 3h et 5h avec ruminations. Jamais de sommeil réparateur."},{"cle":"anxiete","valeur":"Anxiété diffuse, permanente. Palpitations fréquentes au stress. Difficultés de concentration."},{"cle":"chaleur","valeur":"Chaleur dans la poitrine le soir. Sueurs nocturnes. Mains et pieds chauds. Bouche sèche la nuit."},{"cle":"antecedents","valeur":"Burn-out professionnel il y a 18 mois. Jamais complètement récupérée depuis."}],"observation":"Regard anxieux, voix hésitante. Teint légèrement rouge sur les pommettes. Agitation des mains.","prisePouls":{"condition":"Patient allongé, respiration calmée","lectures":[{"position":"foyer_superieur_gauche","qualites":["vide","rapide"],"interpretation":"Cœur vide et rapide — Shen sans ancrage, Yin insuffisant."},{"position":"foyer_inferieur_gauche","qualites":["vide","profond"],"interpretation":"Yin du Rein vide profond — cause du vide de Yin général et du feu du vide."},{"position":"foyer_superieur_droit","qualites":["vide","faible"],"interpretation":"Poumon vide — Qi général insuffisant."}],"synthese":"Vide de Yin du Rein → Feu du vide irrite le Cœur → Shen perturbé. Tableau post-burn-out classique : épuisement du Yin par surmenage chronique."}},"view_count":98,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-11-01","updated_at":"2026-05-11T16:12:09.075Z","date_creation":"2025-11-01","date_publication":"2025-11-20"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-009","slug":"lucie-22-ans-dysmenorrhee-spm","titre":"Lucie, 22 ans — Dysménorrhée invalidante et syndrome prémenstruel","statut":"publie","niveau_complexite":2,"age":22,"sexe":"feminin","cas_complet":true,"exemplaire":false,"grille_principale":"cinq_elements","tags":["dysménorrhée","SPM","Foie","stagnation Qi","vide Sang","règles"],"content":{"motif":"Dysménorrhée invalidante depuis 4 ans avec syndrome prémenstruel marqué — règles douloureuses, ballonnements et anxiété prémenstruelle.","interrogatoire":[{"cle":"regles","valeur":"Douleurs intenses J1-J2, obligeant à l''alitement. Sang rouge foncé avec caillots. Cycle de 28 jours régulier mais douloureux depuis l''adolescence."},{"cle":"spm","valeur":"Les 5-7 jours précédant les règles : seins douloureux, irritabilité majeure, pleurs faciles, ballonnements, envie de sucre."},{"cle":"digestif","valeur":"Ballonnements fréquents en dehors des règles. Alternance diarrhées/constipation selon le stress."},{"cle":"emotionnel","valeur":"Grande sensibilité émotionnelle. Frustration facile. Se sent mieux après avoir pleuré ou après les règles."},{"cle":"froid","valeur":"Appuyer fort sur le ventre soulage. La chaleur (bouillotte) améliore."}],"observation":"Teint légèrement jaune-verdâtre. Ongles fragiles. Légère tension dans les hypocondres.","prisePouls":{"condition":"J14 du cycle (mi-cycle)","lectures":[{"position":"foyer_moyen_gauche","qualites":["corde_arc"],"interpretation":"Corde-arc au Foyer Moyen gauche — Foie en tension, Qi stagnant."},{"position":"foyer_superieur_gauche","qualites":["vide","faible"],"interpretation":"Cœur faible — Sang insuffisant (vide de Sang du Foie)."},{"position":"foyer_inferieur_gauche","qualites":["vide"],"interpretation":"Foyer Inférieur gauche légèrement vide — Sang du Rein insuffisant."}],"synthese":"Stagnation de Qi du Foie sur fond de Vide de Sang. Le Qi stagnant bloque la circulation du Sang à la menstruation → douleurs et caillots."}},"view_count":76,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-11-15","updated_at":"2026-05-11T16:12:09.075Z","date_creation":"2025-11-15","date_publication":"2025-12-01"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
INSERT INTO clinical_cases SELECT * FROM json_populate_record(null::clinical_cases, '{"id":"cas-010","slug":"pierre-50-ans-tendinite-epicondyle","titre":"Pierre, 50 ans — Tendinite épicondyle latéral bras droit","statut":"publie","niveau_complexite":1,"age":50,"sexe":"masculin","cas_complet":true,"exemplaire":false,"grille_principale":"meridiens","tags":["tendinite","épicondylite","méridien GI","TR","coude","Oé/Iong"],"content":{"motif":"Tendinite épicondyle latéral au coude droit depuis 3 mois — douleur irradiant dans l''avant-bras lors de la prise en pronation.","interrogatoire":[{"cle":"douleur","valeur":"Douleur vive à la pression de l''épicondyle latéral. Irradiation vers le poignet lors de la serrage. Aggravée par le geste répété (tennis, travail informatique)."},{"cle":"horaire","valeur":"Mieux le matin, pire en cours de journée. Aggravée par le froid humide."},{"cle":"general","valeur":"Stress professionnel important. Fatigue générale. Travaille 60h/semaine depuis 6 mois."},{"cle":"antecedents","valeur":"Joueur de tennis (3-4h/semaine). Aucun traumatisme. Apparition progressive et insidieuse."}],"observation":"Douleur reproductible à la pression de l''épicondyle latéral. Test de Cozen positif. Pas d''atteinte neurologique.","prisePouls":{"condition":"Patient assis, bras droit examiné","lectures":[{"position":"foyer_superieur_droit","qualites":["vide","superficiel"],"interpretation":"Pouls superficiel vide à droite — Oé en plénitude locale sur fond d''Iong insuffisante."},{"position":"foyer_moyen_droit","qualites":["large","mou"],"interpretation":"Rate légèrement large et mou — Foyer Moyen un peu chargé."},{"position":"global_superficiel","qualites":["vide"],"interpretation":"Pouls global superficiel vide — vide Yang général, fatigue de fond."}],"synthese":"Paradoxe Oé/Iong : chaleur/inflammation locale (Oé en excès) sur fond de vide Yang général (Iong insuffisante). Traiter l''Iong générale ET disperser l''Oé locale."}},"view_count":64,"qualifie_apprentissage":false,"auteur_id":null,"created_at":"2025-12-01","updated_at":"2026-05-11T16:12:09.075Z","date_creation":"2025-12-01","date_publication":"2025-12-15"}') ON CONFLICT (id) DO UPDATE SET titre = EXCLUDED.titre, content = EXCLUDED.content, exemplaire = EXCLUDED.exemplaire;
